// Passa in avanti SOLO se lo stato è cambiato rispetto all'ultimo controllo (evita di
// avvisarti ogni 5 minuti finché il sito resta giù, o su ogni ping quando è su).
const state = $getWorkflowStaticData('global');
const code = $input.first().json.statusCode || 0;
const giu = code === 0 || code >= 500;
const eraGiu = state.giu === true;
if (giu === eraGiu) return [];
state.giu = giu;
return [{ json: { giu, code, quando: new Date().toISOString() } }];
